def prompts(group, i):
    fid, scene, after, before, video = FILMS[group][i]
    return {"id": fid, "scene": scene, "after": AFTER.format(s=after), "before": BEFORE.format(s=before),
            "video": VIDEO.format(s=video)}


if __name__ == "__main__":
    group = sys.argv[1]
    kind = sys.argv[2]  # after | before | video
    out = [{"index": i, "id": FILMS[group][i][0], "prompt": prompts(group, i)[kind]} for i in range(len(FILMS[group]))]
    print(json.dumps(out, indent=1))
